    lines.append("| Silent Share $s$ | $R_{naive}$ (%) | $R_{AT}$ (%) | $R_{union}$ (%) | $P_{naive}$ (%) | $P_{AT}$ (%) | $P_{union}$ (%) | FP / 1,000 Clean (AT) | FP / 1,000 Clean (Naive) |")
    lines.append("|:---:|:---:|:---:|:---:|:---:|:---:|:---:|:---:|:---:|")
