    lines.append("| **0.6 (Post-Prec Crossover)** | 40.0% | 29.1% | 52.7% | 38.4% | 39.0% | 37.2% | 172.5 | 243.2 |")
    lines.append("| **0.8 (Post-Recall Crossover)** | 20.0% | 25.2% | 37.0% | 23.8% | 35.6% | 29.4% | 172.5 | 243.2 |")
    lines.append("| **1.0 (All Stealth)** | 0.0% | 21.2% | 21.2% | 0.0% | 31.8% | 19.3% | 172.5 | 243.2 |")
    lines.append("")
